/**
 * WHAT YOU MADE, DRAWN
 *
 * One picture holding every finished product, cut from supplied sheets on a flat
 * magenta ground and keyed at build time — magenta because nothing in this game
 * is magenta, which is what makes a cut-out clean. Alpha, so a jar sits on label
 * stock and in the dark room equally, and WebP because alpha in PNG at this size
 * costs four times as much.
 *
 * ORDER IS LOAD-BEARING, exactly as in `ingredientSheet.ts`: entry N is cell N.
 * Append to both, never insert.
 *
 * Two kinds of id never get their own cell:
 *   - products that look like another (a lacto cep is the lacto mushroom jar),
 *     which `PRODUCT_ALIAS` maps;
 *   - the generated recipes (`lacto_<sub>_gen` and friends), which `productKey`
 *     folds onto their family's picture.
 *
 * The list is ONE ENTRY PER CELL with single commas. It once had doubled commas,
 * which JavaScript reads as empty slots: a 99-slot array for 57 products, so
 * `indexOf` doubled and nearly every product drew another's picture or none.
 */
export const PRODUCT_COLS = 8;
export const PRODUCT_CELL = 160;

export const PRODUCT_ORDER: string[] = [
  'colatura_bottle', 'fish_sauce', 'cider_vinegar_jar', 'kombucha_jar',
  'makgeolli_jar', 'country_wine_bottle', 'hatcho_miso', 'shiro_miso',
  'gochujang_paste', 'meju_block', 'nut_miso_jar', 'black_garlic_head',
  'kimchi_jar', 'sauerkraut_crock', 'lacto_mushroom_jar', 'brined_plum_jar',
  'maesil_jar', 'tempeh_block', 'salumi_hung', 'blue_wheel',
  'cultured_cream', 'cured_yolk', 'surstromming_tin', 'natto_pack',
  'mushroom_miso_jar', 'bean_miso_jar', 'corn_miso_jar', 'tomato_amino_jar',
  'doenjang_jar', 'doubanjiang_paste', 'mushroom_shoyu_bottle', 'pulse_amino_bottle',
  'ponzu_bottle', 'mushroom_garum_bottle', 'tomato_garum_bottle', 'rose_garum',
  'mead_bottle', 'grain_sake_bottle', 'chicha_pot', 'kvass_bottle',
  'tepache_jar', 'cheong_syrup', 'fruit_kombucha_jar', 'tomato_kombucha_jar',
  'fruit_vinegar_bottle', 'tomato_vinegar_bottle', 'mushroom_vinegar_bottle', 'coconut_vinegar',
  'douchi_jar', 'bagoong_paste', 'peaso_paste', 'scallop_fudge',
  'black_apple', 'bio_sludge', 'lacryma_vial', 'ambrosia',
  'forbidden_cheese', 'lacto_tomato_jar', 'brined_fruit_jar', 'lacto_ceps',
  'nukazuke_jar', 'ricotta_jar', 'chili_mash_cask',
];

/** Ids that share another product's picture. */
export const PRODUCT_ALIAS: Record<string, string> = {
};

/** The family a generated recipe's output belongs to. */
const GENERATED: [RegExp, string][] = [
  [/^lacto_.*_gen$/, 'lacto_mushroom_jar'],
  [/^miso_.*_gen$/, 'hatcho_miso'],
  [/^garum_.*_gen$/, 'colatura_bottle'],
  [/^cheong_.*_gen$/, 'cheong_syrup'],
  [/^black_.*_gen$/, 'black_apple'],
];

/** The cell this id draws, or -1 when the sheet has no picture for it. */
export const productIndex = (id: string): number => {
  const direct = PRODUCT_ORDER.indexOf(id);
  if (direct >= 0) return direct;
  const alias = PRODUCT_ALIAS[id];
  if (alias) return PRODUCT_ORDER.indexOf(alias);
  for (const [re, family] of GENERATED) if (re.test(id)) return PRODUCT_ORDER.indexOf(family);
  return -1;
};

export const PRODUCT_SHEET = "data:image/webp;base64,";
